// ==UserScript==
// @name         xb — 微博 X 风格阅读（去广告 · 清爽时间线 · 媒体下载）
// @namespace    https://github.com/dddaniel1/xb
// @version      1.27.12
// @author       nnecec
// @description  把 weibo.com 重写成 X 风格的专注阅读界面：去广告与推荐干扰、清爽时间线、图片/视频查看与下载、生图导出、自定义主题和字体。开源项目 nnecec/xb 的 Tampermonkey 版。
// @license      GPL-3.0
// @icon         https://raw.githubusercontent.com/dddaniel1/xb/main/public/icon/logo-128.png
// @homepage     https://github.com/dddaniel1/xb
// @homepageURL  https://github.com/dddaniel1/xb
// @source       https://github.com/dddaniel1/xb.git
// @supportURL   https://github.com/dddaniel1/xb/issues
// @match        https://weibo.com/*
// @match        https://www.weibo.com/*
// @connect      weibo.com
// @connect      www.weibo.com
// @connect      m.weibo.cn
// @connect      xb-server.nnecec-3d5.workers.dev
// @connect      cdn.jsdelivr.net
// @connect      sinaimg.cn
// @connect      *.sinaimg.cn
// @connect      sinajs.cn
// @connect      *.sinajs.cn
// @connect      weibocdn.com
// @connect      *.weibocdn.com
// @grant        GM_addValueChangeListener
// @grant        GM_cookie
// @grant        GM_deleteValue
// @grant        GM_getValue
// @grant        GM_listValues
// @grant        GM_removeValueChangeListener
// @grant        GM_setValue
// @grant        GM_xmlhttpRequest
// @grant        unsafeWindow
// @run-at       document-start
// ==/UserScript==

;(async () => {
  // Hide Weibo's native shell while the payload is inflated.
  const antiFlash = document.createElement('style')
  antiFlash.textContent = 'html:not([data-xb-weibo-ready]) #app{visibility:hidden!important}'
  ;(document.head || document.documentElement).appendChild(antiFlash)

  const binary = atob('')
  const bytes = new Uint8Array(binary.length)
  for (let index = 0; index < binary.length; index++) {
    bytes[index] = binary.charCodeAt(index)
  }

  const text = await new Response(
    new Blob([bytes]).stream().pipeThrough(new DecompressionStream('gzip')),
  ).text()

  // eslint-disable-next-line no-eval
  eval(text)
})().catch((error) => {
  console.error('[xb] failed to inflate userscript payload', error)
})
